"""Create a separate MediaMTX candidate config; never overwrite/start a service."""
import argparse
import ipaddress
import json
import os
from pathlib import Path


def prepare(base, codec, hls_port, webrtc_port, ice_host, ice_port, enable_webrtc):
    # Inputs must be the owned router JSON generated by media_router/render_config.py,
    # never the configuration of an unrelated production media service.
    if base.get("rtspAddress") != "127.0.0.1:28554" or base.get("rtmp") is not False:
        raise ValueError("owned_loopback_router_required")
    if base.get("api") or base.get("metrics") or base.get("pprof"):
        raise ValueError("unexpected_control_servers")
    config = json.loads(json.dumps(base))
    raw = {"source": "rtsp://127.0.0.1:12854/camera_main?stream=0" if codec == "original" else "publisher",
           "maxReaders": 4, "record": False, "alwaysAvailable": False,
           "overridePublisher": False, "useAbsoluteTimestamp": False}
    if codec == "original":
        raw.update({"rtspTransport": "tcp", "sourceOnDemand": True,
                    "sourceOnDemandStartTimeout": "20s", "sourceOnDemandCloseAfter": "10s"})
    config["paths"]["raw-main"] = raw
    found_reader = False
    found_local_publisher = codec == "original"
    for user in config["authInternalUsers"]:
        if user.get("user") == "backend_reader" and user.get("ips") == ["127.0.0.1", "::1"]:
            user["permissions"].append({"action": "read", "path": "raw-main"})
            found_reader = True
        if codec == "h264" and user.get("user") == "any" and user.get("ips") == ["127.0.0.1", "::1"]:
            user["permissions"].append({"action": "publish", "path": "raw-main"})
            found_local_publisher = True
    if not found_reader or not found_local_publisher:
        raise ValueError("exact_local_permissions_required")
    config.update({"hls": True, "hlsAddress": f"127.0.0.1:{hls_port}",
                   "hlsEncryption": False, "hlsAllowOrigins": [], "hlsAlwaysRemux": False,
                   "hlsVariant": "fmp4", "hlsSegmentCount": 7, "hlsSegmentDuration": "1s",
                   "hlsSegmentMaxSize": "8M", "hlsMuxerCloseAfter": "10s",
                   "webrtc": enable_webrtc, "webrtcAddress": f"127.0.0.1:{webrtc_port}",
                   "webrtcEncryption": False, "webrtcAllowOrigins": [],
                   "webrtcIPsFromInterfaces": False, "webrtcAdditionalHosts": [ice_host],
                   "webrtcLocalUDPAddress": f"{ice_host}:{ice_port}",
                   "webrtcLocalTCPAddress": "", "webrtcICEServers2": []})
    return config


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--owned-base-json", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--display-codec", choices=("original", "h264"), default="original")
    parser.add_argument("--hls-port", type=int, default=28888)
    parser.add_argument("--webrtc-port", type=int, default=28889)
    parser.add_argument("--ice-port", type=int, default=28890)
    parser.add_argument("--ice-host", default="211.139.12.141")
    parser.add_argument("--enable-webrtc", action="store_true")
    args = parser.parse_args()
    if any(not 1024 <= port <= 65535 for port in (args.hls_port, args.webrtc_port, args.ice_port)):
        parser.error("unprivileged_dedicated_ports_required")
    ipaddress.IPv4Address(args.ice_host)
    if args.output.exists():
        parser.error("existing_config_not_overwritten")
    config = prepare(json.loads(args.owned_base_json.read_text(encoding="utf-8")), args.display_codec,
                     args.hls_port, args.webrtc_port, args.ice_host, args.ice_port, args.enable_webrtc)
    descriptor = os.open(args.output, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(descriptor, "w", encoding="utf-8", newline="\n") as output:
        json.dump(config, output, indent=2)
        output.write("\n")
    print(json.dumps({"candidate_written": True, "display_codec": args.display_codec,
                      "hls_loopback_port": args.hls_port, "webrtc_enabled": args.enable_webrtc,
                      "service_started": False, "existing_file_modified": False, "secrets_logged": False}))


if __name__ == "__main__":
    main()
